    INSERT INTO public.protocols SELECT (jsonb_populate_record(NULL::public.protocols, to_jsonb(src) || '{"id": "6b5268e6-78a7-5cde-bd1e-e56eef8bf55c", "user_id": null, "name": "Conor McGregor \u2022 Fight Camp Cycle", "type": "celebrity", "category": "Fitness", "tags": ["fitness", "celebrity", "mma", "fight-camp"], "creator": "Conor McGregor", "source": "system", "source_attribution": "ESPN (UFC 257 camp); coaches John Kavanagh and Owen Roddy. Public reports only.", "description": "A 4-day fight-camp cycle built on what McGregor''s team has said publicly: two sessions a day for three days (strength or conditioning in the morning, then technical work and sparring in the evening), then one active-recovery day, repeated. In camp the cycle reportedly ran three weeks on and one lighter week, with volume tapering as the fight neared. Recovery days used yoga, rock climbing or fishing. Contact sport: train with a qualified coach. Sources: ESPN on his UFC 257 camp, and coaches John Kavanagh and Owen Roddy. Inspired by publicly reported habits; not affiliated with or endorsed by Conor McGregor. Educational, not medical advice.", "total_days": 4, "is_public": true, "is_active": true, "is_suggested": true, "risk_level": "medium", "effectiveness_evidence": "anecdotal", "image_url": null, "image_prompt": "athletic man in a boxing gym between sparring rounds, wraps on hands, heavy bag, warm tungsten light, cinematic, 16:9 --ar 16:9", "health_score": null, "sort_order": 0, "contraindications": [], "cloned_from": null, "builder_kind": null, "builder_config": null, "source_protocol_ids": null, "frequency": "daily", "frequency_days": null, "phases": null}'::jsonb || jsonb_build_object('created_at', now(), 'updated_at', now()))).*;
