    INSERT INTO public.protocols SELECT (jsonb_populate_record(NULL::public.protocols, to_jsonb(src) || '{"id": "36719947-02bc-53b3-a71d-acac1d9303db", "user_id": null, "name": "Conor McGregor \u2022 Clean Camp Eating", "type": "celebrity", "category": "Diet", "tags": ["diet", "celebrity", "mma", "high-protein"], "creator": "Conor McGregor", "source": "system", "source_attribution": "ESPN (nutritionist Georges Lockhart interviews); fan compilations of interviews and posts, which differ between camps.", "description": "A clean-eating day modelled on what McGregor and his nutritionist Georges Lockhart have described: high protein, carbs from fruit, green vegetables, sweet potato and butternut squash, healthy fats from nuts, oily fish and avocado, and meals timed around training. Menu details come from interviews and fan compilations and vary between camps. Fight-week weight cutting is not part of this routine. Sources: ESPN interviews with his nutritionist and public posts. Inspired by publicly reported habits; not affiliated with or endorsed by Conor McGregor. Educational, not medical advice.", "total_days": null, "is_public": true, "is_active": true, "is_suggested": true, "risk_level": "low", "effectiveness_evidence": "anecdotal", "image_url": null, "image_prompt": "plate of grilled steak, smoked salmon and eggs, sweet potato and greens on a dark kitchen counter, natural light, editorial food photography, 16:9 --ar 16:9", "health_score": null, "sort_order": 0, "contraindications": [], "cloned_from": null, "builder_kind": null, "builder_config": null, "source_protocol_ids": null, "frequency": "daily", "frequency_days": null, "phases": null}'::jsonb || jsonb_build_object('created_at', now(), 'updated_at', now()))).*;
