    INSERT INTO public.protocols SELECT (jsonb_populate_record(NULL::public.protocols, to_jsonb(src) || '{"id": "65ede19c-4408-569c-9059-c4b0461acdc4", "user_id": null, "name": "Erling Haaland \u2022 Fuel", "type": "celebrity", "category": "Diet", "tags": ["diet", "celebrity", "football", "whole-foods"], "creator": "Erling Haaland", "source": "system", "source_attribution": "Men''s Health Australia; The Week; PCRM (Dr Neal Barnard) on raw milk and organ meats. Menus are approximate.", "description": "A week of eating inspired by what is reported about Haaland: whole foods, red meat and fish, eggs, potatoes and rice, asparagus, honey, and organ meats such as beef heart and liver. The reported 6,000 kcal a day is for an elite striker, so portions here are yours to set. Raw milk is reportedly part of his diet; health authorities warn against it, so this routine uses pasteurised milk. Organ meats are kept small: liver no more than once a week, and none during pregnancy. Sources: Men''s Health Australia, The Week and PCRM (Dr Neal Barnard). Menus are approximate. Inspired by publicly reported habits; not affiliated with or endorsed by Erling Haaland. Educational, not medical advice.", "total_days": 7, "is_public": true, "is_active": true, "is_suggested": true, "risk_level": "medium", "effectiveness_evidence": "anecdotal", "image_url": null, "image_prompt": "rustic table with beef heart, steak, sea bass, asparagus, eggs and sourdough, farmhouse kitchen, natural light, editorial food photography, 16:9 --ar 16:9", "health_score": null, "sort_order": 0, "contraindications": [], "cloned_from": null, "builder_kind": null, "builder_config": null, "source_protocol_ids": null, "frequency": "daily", "frequency_days": null, "phases": null}'::jsonb || jsonb_build_object('created_at', now(), 'updated_at', now()))).*;
