    INSERT INTO public.protocols SELECT (jsonb_populate_record(NULL::public.protocols, to_jsonb(src) || '{"id": "44292310-f496-500a-abff-aca32e579393", "user_id": null, "name": "Erling Haaland \u2022 Recovery and Sleep", "type": "celebrity", "category": "Recovery", "tags": ["recovery", "celebrity", "football", "sleep"], "creator": "Erling Haaland", "source": "system", "source_attribution": "Euronews (ice baths, saunas, hypoxic chambers); Goal; sleep reports vary between 8 and 10 hours.", "description": "A recovery routine built on what has been reported about Haaland: ice baths and saunas after training four or five times a week, yoga and mobility, and long sleep, usually in bed around 10pm with devices off. Reports of his sleep range from about 8 to 10 hours. A home cryotherapy chamber and a hypoxic chamber are also reported; those are not part of this routine. Sources: Euronews and Goal. Inspired by publicly reported habits; not affiliated with or endorsed by Erling Haaland. Educational, not medical advice.", "total_days": null, "is_public": true, "is_active": true, "is_suggested": true, "risk_level": "medium", "effectiveness_evidence": "anecdotal", "image_url": null, "image_prompt": "cold plunge tub and sauna in a calm modern spa at dusk, steam, soft blue and amber light, cinematic, 16:9 --ar 16:9", "health_score": null, "sort_order": 0, "contraindications": [], "cloned_from": null, "builder_kind": null, "builder_config": null, "source_protocol_ids": null, "frequency": "daily", "frequency_days": null, "phases": null}'::jsonb || jsonb_build_object('created_at', now(), 'updated_at', now()))).*;
